
const icons={home:'<path d="m3 10 9-7 9 7v10h-6v-6H9v6H3z"/>',budget:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M3 10h18M7 3h10"/>',activity:'<path d="M7 4h14M7 10h14M7 16h14M7 22h14"/><path d="M3 4h.01M3 10h.01M3 16h.01M3 22h.01"/>',insights:'<path d="M4 21V12m6 9V7m6 14V3m5 18H2"/>',plus:'<path d="M12 4v16M4 12h16"/>',up:'<path d="M7 17 17 7M8 7h9v9"/>',down:'<path d="M7 7 17 17m0-9v9H8"/>',saving:'<path d="M4 9c2-7 13-8 16 0 3 8-5 12-9 12S2 17 4 9Z"/><path d="m8 12 3 3 5-6"/>',wallet:'<rect x="2" y="6" width="20" height="15" rx="3"/><path d="M2 9h16a3 3 0 0 1 3 3v2h-5a2 2 0 0 0 0 4h5"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20"/>',phone:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 19h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v5m0-8h.01"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',edit:'<path d="m4 20 4-1 11-11-3-3L5 16z"/>',trash:'<path d="M4 7h16M8 7v13h8V7M9 4h6"/>'};
function ico(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.wallet}</svg>`}
const BASE_CATS=[['salary','Gaji','income','#49b49d','💼'],['bonus','Bonus','income','#74c8aa','✦'],['other-income','Pendapatan lain','income','#6198ea','↗'],['rent','Sewa rumah','expense','#7966e8','⌂'],['groceries','Belanja bulanan','expense','#f6a36c','▤'],['transport','Transportasi','expense','#5f9ce6','⌁'],['food','Makan & minum','expense','#e87d91','♨'],['bills','Tagihan','expense','#48b7c0','▣'],['other-expense','Lainnya','expense','#9ba2b9','✦'],['emergency','Dana darurat','saving','#a5be46','✓'],['invest','Investasi','saving','#8c82ed','↗']].map(([id,label,kind,color,mark])=>({id,label,kind,color,mark}));
const BASE_ACCOUNTS=[['bni','BNI','#5e62ef'],['cash','Tunai','#2eb1a2'],['bri','BRI','#2990ef'],['jago','Jago','#f3a546'],['dana','DANA','#248fd4'],['gopay','GoPay','#2aa5c7'],['ovo','OVO','#a57bce'],['shopeepay','ShopeePay','#ed8253'],['other-account','Lainnya','#ed6a8a']].map(([id,label,color])=>({id,label,color}));
const currentPeriod=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const defaultData=()=>({categories:BASE_CATS.map(x=>({...x})),accounts:BASE_ACCOUNTS.map(x=>({...x,openingBalance:0})),budgets:{},transactions:[]});
// One-time safe cleanup of exact factory records and untouched example budgets.
const MONEO_SAMPLE_ROWS={
  'demo-1':{day:'02',kind:'expense',accountId:'bni',categoryId:'rent',amount:1600000,notes:['Sewa rumah Januari','Sewa rumah bulan ini']},
  'demo-2':{day:'03',kind:'income',accountId:'cash',categoryId:'bonus',amount:300000,notes:['Bonus']},
  'demo-3':{day:'02',kind:'income',accountId:'bni',categoryId:'salary',amount:5300000,notes:['Gaji bulanan']}
};
const MONEO_SAMPLE_TARGETS={salary:5000000,bonus:200000,'other-income':100000,rent:1600000,groceries:2500000,emergency:2000000,invest:1000000};
function isMoneoSampleRow(t){const x=MONEO_SAMPLE_ROWS[t?.id];return !!x && /^\d{4}-(?:0[1-9]|1[0-2])-(?:02|03)$/.test(t.date) && t.date.endsWith('-'+x.day) && t.kind===x.kind && t.accountId===x.accountId && t.categoryId===x.categoryId && t.amount===x.amount && x.notes.includes(t.note)}
function cleanMoneoSamples(book){
  const known=book.transactions.filter(isMoneoSampleRow),remaining=book.transactions.filter(t=>!isMoneoSampleRow(t));
  const budgets={...book.budgets}; const periods=new Set(known.map(t=>t.date.slice(0,7)));periods.add('2025-01'); let targets=0;
  const fullTemplateByPeriod=new Set();
  for(const key of Object.keys(budgets)){const m=/^(\d{4}-(?:0[1-9]|1[0-2]))\|(.+)$/.exec(key);if(!m)continue;const p=m[1];if(!fullTemplateByPeriod.has(p) && Object.entries(MONEO_SAMPLE_TARGETS).every(([cat,amount])=>budgets[`${p}|${cat}`]===amount))fullTemplateByPeriod.add(p)}
  for(const [key,amount] of Object.entries(budgets)) {const m=/^(\d{4}-(?:0[1-9]|1[0-2]))\|(.+)$/.exec(key);if(m && Object.prototype.hasOwnProperty.call(MONEO_SAMPLE_TARGETS,m[2]) && amount===MONEO_SAMPLE_TARGETS[m[2]] && (periods.has(m[1])||fullTemplateByPeriod.has(m[1]))){delete budgets[key];targets++}}
  const changed=known.length>0||targets>0;
  return {data:changed?{...book,transactions:remaining,budgets}:book,changed,rows:known.length,targets};
}

let data,cats,accounts,period=currentPeriod(),active='home',kind='expense',txKind='expense',transFilter='all',query='',privacy=false,selectedDate=null;
let rawCache=null,loadFault=false;
try{rawCache=localStorage.getItem('ana-budget-preview-v1');let obj=rawCache?JSON.parse(rawCache):null,candidate=obj?.data;
  let plausible=candidate&&Array.isArray(candidate.transactions)&&candidate.transactions.every(t=>t&&typeof t.date==='string'&&typeof t.id==='string'&&typeof t.accountId==='string'&&typeof t.categoryId==='string')&&candidate.budgets&&typeof candidate.budgets==='object'&&!Array.isArray(candidate.budgets)&&(!candidate.accounts||Array.isArray(candidate.accounts))&&(!candidate.categories||Array.isArray(candidate.categories));
  if(rawCache&&!plausible)loadFault=true;
  data=plausible?candidate:defaultData();period=currentPeriod();
}catch{if(rawCache)loadFault=true;data=defaultData()}
// Migrate localStorage v1 in-place. Do not lose user transactions when upgrading the preview.
if(!Array.isArray(data.categories))data.categories=BASE_CATS.map(x=>({...x}));
if(!Array.isArray(data.accounts))data.accounts=BASE_ACCOUNTS.map(x=>({...x,openingBalance:0}));
const legacyCollision=data.accounts.some(a=>a.id==='other-account');
const legacyWalletId=legacyCollision?'other-legacy-account':'other-account';
data.accounts.forEach(a=>{if(a.id==='paylater'||a.label.toLowerCase('id-ID')==='paylater'){if(a.id==='paylater'){a.id=legacyWalletId;a.label=legacyCollision?'Lainnya (lama)':'Lainnya'}else a.label='Lainnya'}if(!Number.isSafeInteger(a.openingBalance))a.openingBalance=0});
data.transactions.forEach(t=>{if(t.accountId==='paylater')t.accountId=legacyWalletId});
cats=data.categories;accounts=data.accounts;
if(data.advanced !== undefined && !AnaAdvanced.validate({accounts,categories:cats,advanced:data.advanced})){loadFault=true;}
else if(data.advanced === undefined)data.advanced=AnaAdvanced.fresh();
let cleanupApplied=false;
if(!loadFault){const cleaned=cleanMoneoSamples(data);data=cleaned.data;cats=data.categories;accounts=data.accounts;cleanupApplied=cleaned.changed;}
function persist(){if(loadFault){alert('Data lama rusak atau tidak terbaca. Penyimpanan dicegah agar data asli tidak tertimpa. Unduh data lama dari Pengaturan, lalu pulihkan backup yang valid atau pulihkan backup yang valid.');return}try{localStorage.setItem('ana-budget-preview-v1',JSON.stringify({data,period}))}catch(e){console.warn('Penyimpanan lokal tidak tersedia',e);alert('Gagal menyimpan data ke browser. Ruang penyimpanan penuh atau mode privat aktif. Jangan tutup aplikasi sebelum membuat backup.')}}

if(cleanupApplied && !loadFault){
  try {
    const safetyKey='moneo-before-sample-cleanup-v1110';
    if(rawCache && !localStorage.getItem(safetyKey))localStorage.setItem(safetyKey,rawCache);
    persist();
  }catch(error){loadFault=true;console.warn('Pencadangan data lama gagal; tidak menimpa data sebelumnya',error)}
}

const money=n=>(n<0?'−':'')+'Rp '+Math.round(Math.abs(n)).toLocaleString('id-ID');const short=n=>Math.abs(n)>=1e6?(n/1e6).toFixed(1).replace('.',',')+' jt':Math.abs(n)>=1e3?Math.round(n/1e3)+' rb':String(n);
const show=n=>privacy?'••••••':money(n);
const months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];const sm=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
const monthlabel=p=>months[+p.slice(5)-1]+' '+p.slice(0,4);
function validDay(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;let[y,m,d]=date.split('-').map(Number),n=new Date(y,m-1,d);return n.getFullYear()===y&&n.getMonth()===m-1&&n.getDate()===d}
function dateLabel(date){if(!validDay(date))return date;let[y,m,d]=date.split('-').map(Number);return ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'][new Date(y,m-1,d).getDay()]+', '+d+' '+months[m-1]+' '+y}
function shiftDate(date,delta){if(!validDay(date))return date;let[y,m,d]=date.split('-').map(Number),n=new Date(y,m-1,d+delta);return n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0')}
function dayTotals(date){let tx=data.transactions.filter(t=>t.date===date);let total=k=>tx.filter(t=>t.kind===k).reduce((s,t)=>s+t.amount,0);return {count:tx.length+advState().transfers.filter(t=>t.date===date).length,income:total('income'),expense:total('expense'),saving:total('saving')}}

function addMonth(p,d){let [y,m]=p.split('-').map(Number);let dt=new Date(y,m-1+d,1);return dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')}
function entries(p=period){return data.transactions.filter(x=>x.date.slice(0,7)===p)}
function sum(p,k){return entries(p).filter(t=>t.kind===k).reduce((s,t)=>s+t.amount,0)}
function catSum(p,id){return entries(p).filter(t=>t.categoryId===id).reduce((s,t)=>s+t.amount,0)}
function budget(p,k){return cats.filter(c=>c.kind===k).reduce((s,c)=>s+(k==='expense'?AnaAdvanced.plannedBudget(exportBook(),p,c.id):(data.budgets[p+'|'+c.id]||0)),0)}
function balance(id){return (accounts.find(a=>a.id===id)?.openingBalance||0)+data.transactions.filter(t=>t.accountId===id).reduce((s,t)=>s+(t.kind==='income'?t.amount:-t.amount),0)+AnaAdvanced.accountDelta({advanced:data.advanced},id)}
function totalBalance(){return accounts.reduce((s,a)=>s+balance(a.id),0)}
function progress(pct,color='var(--purple)'){return `<div class="progress"><i style="width:${Math.max(0,Math.min(100,pct*100))}%;background:${color}"></i></div>`}
function safeColor(v){return /^#[0-9a-fA-F]{6}$/.test(v||'')?v:'#7365ec'}
function ci(c,size=43){return `<span class="tx-icon" style="height:${size}px;width:${size}px;background:${safeColor(c.color)}19;color:${safeColor(c.color)};font-size:${Math.round(size*.5)}px;font-weight:950">${esc(c.mark||'●')}</span>`}
function mini(title,n,col,bg,icon){return `<div class="mini"><div class="mini-icon" style="background:${bg};color:${col}">${ico(icon,21)}</div><small>${title}</small><b>${privacy?'••••':short(n)}</b></div>`}
function head(title,action,fn){return `<div class="section-title">${title}${action?`<button onclick="${fn}">${action} ›</button>`:''}</div>`}
function txRow(t,deleteBtn=false){let c=cats.find(c=>c.id===t.categoryId)||{label:'Kategori terhapus',color:'#A5A5BB',mark:'?'},a=accounts.find(a=>a.id===t.accountId);return `<div class="tx">${ci(c)}<div class="tx-body"><b>${esc(c.label)}</b><small>${esc(t.date.slice(8))} · ${esc(a?.label||'?')} · ${esc(t.note)}</small></div><div class="tx-money" style="color:${t.kind==='income'?'#219979':'#17182b'}">${privacy?'••••':(t.kind==='income'?'+':'−')+money(t.amount)}</div>${deleteBtn?`<div class="tx-actions"><button aria-label="Edit transaksi" onclick="editTx('${t.id}')">Edit</button><button aria-label="Hapus transaksi" class="tx-del" onclick="delTx('${t.id}')">×</button></div>`:''}</div>`}
function drawChart(){let series=Array.from({length:6},(_,i)=>addMonth(period,i-5));let inc=series.map(p=>sum(p,'income')),exp=series.map(p=>sum(p,'expense'));let max=Math.max(1000000,...inc,...exp)*1.15,w=340,h=130;const pts=a=>a.map((v,i)=>[10+i*64,12+(1-v/max)*98]);const path=a=>pts(a).map((p,i)=>(i?'L':'M')+p[0]+' '+p[1]).join(' ');let p=pts(inc);let fill=path(inc)+`L${p[5][0]} 113 L${p[0][0]} 113 Z`;
return `<div class="flex" style="justify-content:flex-start;gap:17px;margin-bottom:5px"><div class="legend"><i class="dot" style="background:#7665eb"></i>Pemasukan</div><div class="legend"><i class="dot" style="background:#f8ae79"></i>Pengeluaran</div></div><svg class="chart" viewBox="0 0 340 130" preserveAspectRatio="none"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7665eb" stop-opacity=".18"/><stop offset="1" stop-color="#7665eb" stop-opacity="0"/></linearGradient></defs><path d="M5 12H335 M5 61H335 M5 113H335" fill="none" stroke="#eef0f6" stroke-dasharray="4,5"/><path d="${fill}" fill="url(#chartFill)"/><path d="${path(exp)}" fill="none" stroke="#f8ae79" stroke-width="3" stroke-linecap="round"/><path d="${path(inc)}" fill="none" stroke="#7665eb" stroke-width="3" stroke-linecap="round"/>${p.map((v,i)=>`<circle cx="${v[0]}" cy="${v[1]}" r="${i===5?4:2.5}" fill="#7665eb" stroke="white" stroke-width="1.4"/>`).join('')}</svg><div class="months">${series.map(p=>`<span>${sm[+p.slice(5)-1]}</span>`).join('')}</div>`}
function home(){const income=sum(period,'income'),expense=sum(period,'expense'),saving=sum(period,'saving'),bp=budget(period,'expense');let ranked=[...accounts].map(a=>({...a,value:balance(a.id)})).filter(a=>a.value!==0).sort((a,b)=>b.value-a.value).slice(0,3);let tx=[...entries()].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return `<div class="hero"><div class="hero-top"><span>TOTAL SALDO SEMUA AKUN</span><button onclick="togglePrivacy()">${privacy?'◉':'◯'}</button></div><div class="balance">${show(totalBalance())}</div><div class="hero-bottom"><span class="pill">Saldo dihitung otomatis</span><button class="hero-action" onclick="showAccounts()">Detail akun ›</button></div></div><div class="mini-grid">${mini('Pemasukan',income,'#2ba88d','#e5f8f0','down')}${mini('Pengeluaran',expense,'#e88a6c','#fff0e6','up')}${mini('Tabungan',saving,'#8a78cb','#f0ecff','saving')}</div>${head('Akses cepat')}<div class="quick"><button onclick="add('expense')"><span class="icon" style="background:#fff0e5;color:#e9a16d">${ico('up',27)}</span>Pengeluaran</button><button onclick="add('income')"><span class="icon" style="background:#e8f8f2;color:#36b59a">${ico('down',27)}</span>Pemasukan</button><button onclick="add('saving')"><span class="icon" style="background:#efebff;color:#8c7cd8">${ico('saving',27)}</span>Tabungan</button></div>${head('Anggaran bulan ini','Lihat anggaran',"tab('budget')")}<div class="panel"><div class="flex"><div><div class="hint">Pengeluaran terpakai</div><div class="strong">${show(expense)}</div></div><span class="percent">${bp?Math.round(expense/bp*100)+'%':'Belum diatur'}</span></div>${progress(bp?expense/bp:0,bp&&expense>bp?'#f19880':'#7365ec')}<div class="flex" style="margin-top:11px"><span class="hint">Dari ${show(bp)} budget</span><b class="hint">${bp?(expense>bp?'Lebih '+short(expense-bp):'Sisa '+short(bp-expense)):'Atur budget'}</b></div></div>${head('Arus kas 6 bulan','Analisis',"tab('insights')")}<div class="panel">${drawChart()}</div>${head('Akun terhubung','Semua akun','showAccounts()')}<div class="accounts-preview">${ranked.length?ranked.map(a=>`<div class="acct-card"><div class="tx-icon" style="background:${a.color}18;color:${a.color};height:34px;width:34px">${ico('card',19)}</div><b>${esc(a.label)}</b><small>${privacy?'•••':short(a.value)}</small></div>`).join(''):`<div class="panel">Belum ada saldo</div>`}</div>${head('Transaksi terbaru','Lihat semua',"tab('activity')")}<div class="panel panel-tight">${tx.length?tx.slice(0,4).map(x=>txRow(x)).join(''):'<div class="not-set">Belum ada transaksi bulan ini</div>'}</div><div class="footer-note">Arus kas bersih ${monthlabel(period)}: ${show(income-expense-saving)}</div>`}
function budgets(){let bp=budget(period,kind),actual=sum(period,kind);let list=cats.filter(c=>c.kind===kind);let labels={expense:'Pengeluaran',income:'Pemasukan',saving:'Tabungan'};return `<div class="headline">Atur anggaran</div><div class="subhead">Rencanakan lebih baik, belanja lebih bijak.</div><div class="segmented">${['expense','income','saving'].map(k=>`<button class="${kind===k?'active':''}" onclick="setKind('${k}')">${labels[k]}</button>`).join('')}</div><div class="budget-hero"><small>TARGET ${labels[kind].toUpperCase()}</small><b>${show(bp)}</b><p>${show(actual)} terealisasi · ${bp?Math.round(actual/bp*100)+'%':'Belum ada target'}</p>${progress(bp?actual/bp:0)}</div>${bp===0?`<button class="copy-btn" onclick="copyBudget()">✦ Salin target dari bulan sebelumnya ›</button>`:''}${head('Kategori & target','+ Tambah',"openBudgetCategory()")}<div class="panel panel-tight">${!list.length?'<div class="not-set">Belum ada kategori. Tekan + Tambah di atas.</div>':''}${list.map(c=>{let planned=kind==='expense'?AnaAdvanced.plannedBudget(exportBook(),period,c.id):(data.budgets[period+'|'+c.id]||0),act=catSum(period,c.id);return `<div class="bud-row" onclick="openBudgetCategory('${c.id}')">${ci(c)}<div class="bud-main"><div class="flex"><b>${esc(c.label)}</b><span style="color:#aba7bf">${ico('edit',15)}</span></div>${progress(planned?act/planned:0,planned&&act>planned?'#f49c82':c.color)}<div class="flex"><small>${privacy?'•••':money(act)} realisasi</small><small>${privacy?'•••':money(planned)} target</small></div></div></div>`}).join('')}</div><div class="footer-note">Ketuk kategori untuk mengubah target. ${advState().settings.rollover&&kind==='expense'?'Target di atas sudah termasuk sisa budget yang dibawa dari bulan sebelumnya.':''}</div>`}
function activityBase(){let day=selectedDate?.startsWith(period)?selectedDate:null,totals=day?dayTotals(day):null;let list=entries().filter(t=>(!day||t.date===day)&&(transFilter==='all'||t.kind===transFilter)&&`${t.note} ${cats.find(c=>c.id===t.categoryId)?.label} ${accounts.find(a=>a.id===t.accountId)?.label} ${t.date}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return `<div class="headline">Aktivitas uang</div><div class="subhead">Pilih tanggal untuk melihat transaksi pada hari itu.</div><div class="day-card"><div class="day-control"><div><small>PERIODE TRANSAKSI</small><div class="day-date">${day?dateLabel(day):'Semua tanggal · '+monthlabel(period)}</div></div><button class="day-open" aria-label="Buka kalender transaksi harian" onclick="dayPicker()">▦ Tanggal</button></div><div class="day-actions"><button aria-label="Hari sebelumnya" onclick="goDay(shiftDate('${day||period+'-01'}',-1))">‹</button><button onclick="clearDay()">Semua tanggal</button><button aria-label="Hari berikutnya" onclick="goDay(shiftDate('${day||period+'-01'}',1))">›</button></div>${totals?`<div class="day-stats"><div class="day-stat"><small>Pemasukan</small><b style="color:#299982">${privacy?'••••':money(totals.income)}</b></div><div class="day-stat"><small>Pengeluaran</small><b style="color:#da806f">${privacy?'••••':money(totals.expense)}</b></div><div class="day-stat"><small>Tabungan</small><b style="color:#8774c9">${privacy?'••••':money(totals.saving)}</b></div></div>`:''}</div><div style="position:relative"><input class="search" id="search" placeholder="Cari transaksi, akun, kategori..." value="${esc(query)}" oninput="searchTx(this.value)"/></div><div class="chips">${[['all','Semua'],['expense','Pengeluaran'],['income','Pemasukan'],['saving','Tabungan']].map(([k,t])=>`<button class="chip ${transFilter===k?'active':''}" onclick="setFilter('${k}')">${t}</button>`).join('')}</div><div class="flex" style="margin:5px 0 12px"><b style="font-size:13px">${list.length} transaksi</b><small class="hint">Edit atau hapus transaksi</small></div><div class="panel panel-tight" id="activity-list">${list.length?list.map(x=>txRow(x,true)).join(''):`<div class="not-set">${day?'Tidak ada transaksi pada tanggal ini':'Tidak ada transaksi yang cocok'}</div>`}</div>`}
function insights(){let expense=sum(period,'expense'),income=sum(period,'income'),saving=sum(period,'saving'),net=income-expense-saving;let rank=cats.filter(c=>c.kind==='expense').map(c=>({...c,value:catSum(period,c.id)})).filter(c=>c.value>0).sort((a,b)=>b.value-a.value);let degrees=0,sections=[];rank.forEach(c=>{let end=degrees+c.value/(expense||1)*360;sections.push(`${c.color} ${degrees}deg ${end}deg`);degrees=end});let donut=sections.length?'conic-gradient('+sections.join(',')+')':'#eceefa';return `<div class="headline">Analisis keuangan</div><div class="subhead">Kenali kebiasaan finansialmu.</div><div class="hero" style="min-height:135px"><div class="hero-top"><span>ARUS KAS BERSIH</span></div><div class="balance" style="margin:14px 0 10px">${show(net)}</div><div style="color:#dfdaef;font-size:11px">${net>=0?'✓ Pemasukan menutup pengeluaran dan alokasi tabungan':'! Arus kas bersih negatif'}</div></div>${head('Distribusi pengeluaran')}<div class="panel"><div class="donut-wrap"><div class="donut" style="background:${donut}"><div class="donut-text"><div><small>Total keluar</small><b>${privacy?'•••':short(expense)}</b></div></div></div><div class="legend-list">${rank.length?rank.slice(0,4).map(c=>`<div class="legend-row"><span class="dot" style="background:${c.color}"></span><div><span>${c.label}</span><small>${Math.round(c.value/expense*100)}% · ${privacy?'•••':short(c.value)}</small></div></div>`).join(''):'<div class="hint">Belum ada pengeluaran.</div>'}</div></div></div>${head('Tren pemasukan & pengeluaran')}<div class="panel">${drawChart()}</div>${head('Kategori terbesar')}<div class="panel">${rank.length?rank.slice(0,5).map(c=>`<div style="margin:13px 0"><div class="flex"><b style="font-size:12px">${esc(c.label)}</b><small class="hint">${show(c.value)}</small></div>${progress(c.value/rank[0].value,c.color)}</div>`).join(''):'<div class="not-set">Belum ada data</div>'}</div>${head('Kesehatan budget')}<div class="panel"><div class="flex"><span class="hint">Pengeluaran / target</span><b>${budget(period,'expense')?Math.round(expense/budget(period,'expense')*100)+'%':'—'}</b></div>${progress(budget(period,'expense')?expense/budget(period,'expense'):0)}<div class="flex" style="margin-top:18px"><div><span class="hint">Tabungan</span><div class="strong" style="font-size:15px">${show(saving)}</div></div><div><span class="hint">Target tabungan</span><div class="strong" style="font-size:15px">${show(budget(period,'saving'))}</div></div></div></div>`}
function render(){document.getElementById('page').innerHTML=(loadFault?'<div style="padding:13px;border:1px solid #e1ab89;background:#fff0dd;color:#7b4031;border-radius:12px;margin-bottom:12px;font-size:12px">Peringatan: data tersimpan tidak dapat dibaca. Data asli tidak ditimpa. Buka Pengaturan untuk mengunduh data lama dan melakukan pemulihan.</div>':'')+{home:home,budget:budgets,activity,insights,advanced:advancedPage}[active]()+`<div class="copyright-footer">© 2026 Na · Moneo v1.1.14</div>`;document.getElementById('section-name').textContent={home:'Beranda',budget:'Anggaran',activity:'Aktivitas',insights:'Analisis',advanced:'Keuangan'}[active];document.getElementById('period-label').textContent=monthlabel(period);document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===active));document.querySelectorAll('[data-i]').forEach(el=>{el.innerHTML=ico(el.dataset.i,el.dataset.i==='plus'?26:23)})}
function tab(t){active=t;render();document.getElementById('page').scrollTop=0}
function move(n){period=addMonth(period,n);selectedDate=null;persist();render()}
function togglePrivacy(){privacy=!privacy;render()}
function setKind(k){kind=k;render()}
function setFilter(k){transFilter=k;render()}
function searchTx(s){query=s;let n=s.length;render();let el=document.getElementById('search');if(el){el.focus();el.setSelectionRange(n??s.length,n??s.length)}}
function esc(s){return String(s||'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]))}
function modal(html){document.getElementById('sheet').innerHTML='<div class="handle"></div>'+html;document.getElementById('modal').classList.add('open')}
function closeModal(){document.getElementById('modal').classList.remove('open')}
function modHead(title,desc){return `<div class="modal-head"><div><h2>${title}</h2><p>${desc||''}</p></div><button class="close" onclick="closeModal()">×</button></div>`}
function editTx(id){let tx=data.transactions.find(t=>t.id===id);if(tx)add(tx.kind,id)}
function add(k,editId=''){txKind=k;const old=data.transactions.find(t=>t.id===editId),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;const date=old?.date||(selectedDate?.startsWith(period)?selectedDate:today.startsWith(period)?today:period+'-01');let category=old&&old.kind===txKind?old.categoryId:cats.find(c=>c.kind===txKind)?.id||'';modal(modHead(old?'Edit transaksi':'Tambah transaksi','Perbaiki nominal, dompet, kategori, tanggal atau catatan.')+`<div class="segmented">${[['expense','Pengeluaran'],['income','Pemasukan'],['saving','Tabungan']].map(([key,title])=>`<button class="${txKind===key?'active':''}" onclick="add('${key}','${editId}')">${title}</button>`).join('')}</div><div class="field"><label>NOMINAL RUPIAH</label><div class="amount-box">Rp <input id="amount" type="text" inputmode="numeric" placeholder="0" value="${old?.amount||''}" /></div></div><div class="field"><label>KATEGORI</label><select id="cat">${cats.filter(c=>c.kind===txKind).map(c=>`<option value="${c.id}" ${c.id===category?'selected':''}>${esc(c.label)}</option>`).join('')}</select>${!cats.some(c=>c.kind===txKind)?'<small class="hint">Belum ada kategori. Buat di menu Anggaran.</small>':''}</div><div class="field"><label>${txKind==='income'?'MASUK KE DOMPET':'DARI DOMPET'}</label><select id="acc">${accounts.map(a=>`<option value="${a.id}" ${a.id===old?.accountId?'selected':''}>${esc(a.label)}</option>`).join('')}</select>${!accounts.length?'<button class="manage-add" onclick="showAccounts()">+ Tambah dompet dulu</button>':''}</div><div class="field"><label>TANGGAL</label><input type="date" id="date" value="${date}" /></div><div class="field"><label>CATATAN (OPSIONAL)</label><input id="note" maxlength="160" value="${esc(old?.note||'')}" placeholder="Misalnya: Sewa rumah"/></div><div class="error" id="formError"></div><button class="save-btn" onclick="saveTransaction('${editId}')">✓ ${old?'Simpan perubahan':'Simpan transaksi'}</button>`)}
function saveTransaction(editId=''){const moneyInput=document.getElementById('amount')?.value.trim()||'',amount=Number(moneyInput.replace(/\D/g,'')),date=document.getElementById('date')?.value||'',cat=document.getElementById('cat')?.value||'',acc=document.getElementById('acc')?.value||'',note=document.getElementById('note')?.value.trim()||'';if(!(Number.isSafeInteger(amount)&&amount>0&&amount<1e15)||!validDay(date)||!cats.some(c=>c.id===cat&&c.kind===txKind)||!accounts.some(a=>a.id===acc)||note.length>160){formError('Periksa nominal, tanggal, kategori, dompet dan catatan (maksimal 160 karakter).');return}if(editId&&!data.transactions.some(t=>t.id===editId)){formError('Transaksi lama tidak ditemukan.');return}let tx={id:editId||makeId('tx'),date,kind:txKind,categoryId:cat,accountId:acc,amount,note};if(editId)data.transactions=data.transactions.map(t=>t.id===editId?tx:t);else data.transactions.unshift(tx);period=date.slice(0,7);selectedDate=date;persist();closeModal();render()}

function makeId(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9)}
function nameClean(v){return v.trim().replace(/\s+/g,' ').slice(0,44)}
function formError(msg){let el=document.getElementById('formError');if(el){el.textContent=msg;el.style.display='block'}}
function openBudgetCategory(id){
  let c=cats.find(c=>c.id===id),old=c?(data.budgets[period+'|'+id]||0):0;
  modal(modHead(c?'Edit kategori & anggaran':'Tambah kategori '+({expense:'pengeluaran',income:'pemasukan',saving:'tabungan'}[kind]),'Untuk '+monthlabel(period))+
  `<div class="field"><label>NAMA KATEGORI</label><input id="catname" maxlength="44" placeholder="Contoh: Belanja harian" value="${esc(c?.label||'')}"></div>`+
  `<div class="field"><label>TARGET BULAN INI (RP)</label><small class="hint">Isi 0 untuk menghapus target bulan ini tanpa menghapus kategori.</small><div class="amount-box" style="margin-top:9px">Rp <input id="newbudget" type="text" inputmode="numeric" value="${old}"></div></div>`+
  `<div class="error" id="formError"></div><button class="save-btn" onclick="saveBudgetCategory('${id||''}')">✓ ${c?'Simpan perubahan':'Tambah kategori'}</button>`+
  (c?`<button class="danger-btn" onclick="askDeleteCategory('${c.id}')">${ico('trash',17)} Hapus kategori</button>`:''));
}
function saveBudgetCategory(id){
  let c=cats.find(c=>c.id===id),name=nameClean(document.getElementById('catname').value),raw=document.getElementById('newbudget').value,amount=Number(raw.replace(/\D/g,'')),selectedKind=c?.kind||kind;
  if(!name){formError('Nama kategori wajib diisi.');return}
  if(cats.some(x=>x.id!==id&&x.kind===selectedKind&&x.label.toLocaleLowerCase('id-ID')===name.toLocaleLowerCase('id-ID'))){formError('Nama kategori sudah ada pada jenis ini.');return}
  if(!Number.isSafeInteger(amount)||amount<0||amount>=1e15){formError('Nominal target tidak valid.');return}
  if(c)c.label=name;
  else{let theme={expense:['#e48b81','✦'],income:['#32af98','↗'],saving:['#8d80e6','✓']}[selectedKind];c={id:makeId('category'),label:name,kind:selectedKind,color:theme[0],mark:theme[1]};cats.push(c)}
  data.budgets[period+'|'+c.id]=amount;persist();closeModal();render();
}
function askDeleteCategory(id){let c=cats.find(x=>x.id===id);if(!c)return;
  if(data.transactions.some(t=>t.categoryId===id)||advState().recurring.some(r=>r.categoryId===id)){formError('Kategori masih memiliki transaksi. Hapus transaksi terkait dahulu agar riwayat tetap akurat.');return}
  modal(modHead('Hapus kategori?', 'Kategori '+esc(c.label)+' dan semua target bulannya akan dihapus.')+
  `<p class="hint">Transaksi yang menggunakan kategori ini tidak boleh ada.</p><button class="danger-btn" onclick="doDeleteCategory('${id}')">Hapus kategori</button><button class="save-btn secondary" onclick="openBudgetCategory('${id}')">Batal</button>`)
}
function doDeleteCategory(id){if(data.transactions.some(t=>t.categoryId===id)||advState().recurring.some(r=>r.categoryId===id))return;data.categories=data.categories.filter(c=>c.id!==id);cats=data.categories;Object.keys(data.budgets).forEach(k=>{if(k.endsWith('|'+id))delete data.budgets[k]});persist();closeModal();render()}
// Backward-compatible entry point for older user flows.
function editBudget(id){openBudgetCategory(id)}
function copyBudget(){let p=addMonth(period,-1),found=cats.some(c=>(data.budgets[p+'|'+c.id]||0)>0);if(!found){modal(modHead('Belum ada anggaran','Bulan sebelumnya belum memiliki target anggaran.')+`<button class="save-btn" onclick="closeModal()">Mengerti</button>`);return}modal(modHead('Salin target anggaran','Dari '+monthlabel(p)+' ke '+monthlabel(period))+`<p class="hint">Seluruh target bulan ini akan ditimpa dengan target dari bulan sebelumnya.</p><button class="save-btn" onclick="doCopyBudget()">Salin anggaran</button>`)}
function doCopyBudget(){let p=addMonth(period,-1);cats.forEach(c=>{data.budgets[period+'|'+c.id]=data.budgets[p+'|'+c.id]||0});persist();closeModal();render()}
function delTx(id){let t=data.transactions.find(x=>x.id===id);if(!t)return;modal(modHead('Hapus transaksi?','Jumlah '+money(t.amount)+' pada '+t.date)+`<p class="hint">Transaksi yang dihapus akan mengubah saldo dan laporan bulan terkait.</p><button class="save-btn" style="background:#db686e" onclick="doDelete('${id}')">Hapus transaksi</button><button class="save-btn" style="background:#f3f3f7;color:#666" onclick="closeModal()">Batal</button>`)}
function doDelete(id){data.transactions=data.transactions.filter(t=>t.id!==id);persist();closeModal();render()}
function showAccounts(){modal(modHead('Dompet & rekening','Saldo berdasarkan seluruh transaksi tercatat')+
  `<button class="manage-add" onclick="editAccount()">${ico('plus',18)} Tambah dompet / rekening</button>`+
  (accounts.length?accounts.map(a=>`<button class="account-row account-click" onclick="editAccount('${a.id}')" aria-label="Edit dompet ${esc(a.label)}"><div class="tx-icon" style="background:${a.color}1a;color:${a.color}">${ico('wallet',19)}</div><div class="tx-body"><b>${esc(a.label)}</b><small>Ketuk untuk edit / hapus</small></div><strong>${show(balance(a.id))}</strong><span class="edit-mark">✎</span></button>`).join(''):'<div class="not-set">Belum ada dompet.</div>'))}
function editAccount(id){let a=accounts.find(x=>x.id===id);modal(modHead(a?'Edit dompet / rekening':'Tambah dompet / rekening','Bisa digunakan untuk bank, tunai, atau e-wallet.')+
  `<div class="field"><label>NAMA DOMPET</label><input id="acctname" maxlength="44" placeholder="Contoh: BCA, ShopeePay, Lainnya" value="${esc(a?.label||'')}"></div>`+
  `<div class="field"><label>SALDO AWAL (RP)</label><div class="amount-box">Rp <input id="opening" type="text" inputmode="numeric" value="${a?.openingBalance||0}"></div></div>`+
  `<p class="hint" style="line-height:1.6">Saldo awal + pemasukan − pengeluaran − alokasi tabungan.</p>`+
  `<div class="error" id="formError"></div><button class="save-btn" onclick="saveAccount('${id||''}')">✓ Simpan dompet</button>`+
  (a?`<button class="danger-btn" onclick="askDeleteAccount('${a.id}')">${ico('trash',17)} Hapus dompet</button>`:'')+
  `<button class="save-btn secondary" onclick="showAccounts()">Kembali ke daftar</button>`)}
function saveAccount(id){let a=accounts.find(x=>x.id===id),name=nameClean(document.getElementById('acctname').value),raw=document.getElementById('opening').value,openingBalance=Number(raw.replace(/\D/g,''));
  if(!name){formError('Nama dompet wajib diisi.');return}
  if(accounts.some(x=>x.id!==id&&x.label.toLocaleLowerCase('id-ID')===name.toLocaleLowerCase('id-ID'))){formError('Nama dompet sudah digunakan.');return}
  if(!Number.isSafeInteger(openingBalance)||openingBalance>=1e15){formError('Saldo awal tidak valid.');return}
  if(a){a.label=name;a.openingBalance=openingBalance}
  else accounts.push({id:makeId('account'),label:name,openingBalance,color:['#7063e8','#26aa92','#ef9b73','#4996da'][accounts.length%4]});
  persist();showAccounts();render();
}
function askDeleteAccount(id){let a=accounts.find(x=>x.id===id);if(!a)return;
  if(data.transactions.some(t=>t.accountId===id)||(()=>{let s=advState();return s.transfers.some(t=>t.from===id||t.to===id)||s.allocations.some(a=>a.accountId===id)||s.recurring.some(r=>r.accountId===id)||s.debts.some(d=>d.accountId===id)||s.payments.some(p=>p.accountId===id)||s.adjustments.some(a=>a.accountId===id)})()){formError('Dompet masih memiliki transaksi. Hapus atau pindahkan transaksi terlebih dahulu.');return}
  modal(modHead('Hapus dompet?', 'Dompet '+esc(a.label)+' akan dihapus dari daftar.')+
    `<button class="danger-btn" onclick="doDeleteAccount('${id}')">Hapus dompet</button><button class="save-btn secondary" onclick="editAccount('${id}')">Batal</button>`)}
function doDeleteAccount(id){if(data.transactions.some(t=>t.accountId===id)||(()=>{let s=advState();return s.transfers.some(t=>t.from===id||t.to===id)||s.allocations.some(a=>a.accountId===id)||s.recurring.some(r=>r.accountId===id)||s.debts.some(d=>d.accountId===id)||s.payments.some(p=>p.accountId===id)||s.adjustments.some(a=>a.accountId===id)})())return;data.accounts=data.accounts.filter(a=>a.id!==id);accounts=data.accounts;persist();showAccounts();render()}
function goDay(date){if(!validDay(date))return;period=date.slice(0,7);selectedDate=date;persist();render()}
function clearDay(){selectedDate=null;render()}
let dayPickerPeriod=period;
function dayPicker(){dayPickerPeriod=period;renderDayPicker()}
function calendarShift(delta){dayPickerPeriod=addMonth(dayPickerPeriod,delta);renderDayPicker()}
function dayChoose(date){goDay(date);closeModal()}
function showDayMonth(){period=dayPickerPeriod;selectedDate=null;persist();closeModal();render()}
function todayDay(){let n=new Date();dayChoose(n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0'))}
function renderDayPicker(){let[y,m]=dayPickerPeriod.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,length=new Date(y,m,0).getDate(),days=Array(offset).fill(null).concat(Array.from({length},(_,i)=>dayPickerPeriod+'-'+String(i+1).padStart(2,'0')));while(days.length%7)days.push(null);let counts={};for(let tx of entries(dayPickerPeriod))counts[tx.date]=(counts[tx.date]||0)+1;for(let t of advState().transfers.filter(t=>t.date.startsWith(dayPickerPeriod)))counts[t.date]=(counts[t.date]||0)+1;
  modal(modHead('Kalender transaksi','Ketuk tanggal untuk melihat aktivitas harian.')+
  `<div class="calendar-top"><button aria-label="Kalender bulan sebelumnya" onclick="calendarShift(-1)">‹</button><b>${monthlabel(dayPickerPeriod)}</b><button aria-label="Kalender bulan berikutnya" onclick="calendarShift(1)">›</button></div>`+
  `<div class="calendar-week">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<span>${x}</span>`).join('')}</div>`+
  `<div class="calendar-grid">${days.map(d=>d?`<button aria-label="${dateLabel(d)}, ${counts[d]||0} transaksi" class="${selectedDate===d?'selected':''} ${counts[d]?'has-tx':''}" onclick="dayChoose('${d}')">${Number(d.slice(8))}</button>`:'<button class="blank" tabindex="-1" disabled></button>').join('')}</div>`+
  `<div class="calendar-bottom"><button onclick="showDayMonth()">Semua tanggal</button><button onclick="todayDay()">Hari ini</button></div><p class="hint" style="margin-top:13px">Titik hijau = ada transaksi pada tanggal tersebut.</p>`);
}
function monthPicker(){pickerYear=+period.slice(0,4);renderMonthPicker()}
let pickerYear=2025;
function pickerShift(delta){pickerYear=Math.max(1900,Math.min(2100,pickerYear+delta));renderMonthPicker()}
function renderMonthPicker(){modal(modHead('Pilih bulan & tahun','Tampilkan transaksi dan anggaran bulan tertentu.')+
  `<div class="year-bar"><button aria-label="Tahun sebelumnya" onclick="pickerShift(-1)">‹</button><b>${pickerYear}</b><button aria-label="Tahun berikutnya" onclick="pickerShift(1)">›</button></div>`+
  `<div class="month-grid">${months.map((m,i)=>`<button class="${period===pickerYear+'-'+String(i+1).padStart(2,'0')?'selected':''}" onclick="selectMonth(${i+1})">${sm[i]}</button>`).join('')}</div>`)}
function selectMonth(month){period=pickerYear+'-'+String(month).padStart(2,'0');selectedDate=null;persist();closeModal();render()}
function categoryNativeIcon(c){return c.icon||({salary:'briefcase',bonus:'sparkles','other-income':'trending-up',rent:'home',groceries:'basket',transport:'car',food:'restaurant',bills:'receipt','other-expense':'grid',emergency:'shield-checkmark',invest:'analytics'}[c.id]||({income:'trending-up',expense:'grid',saving:'savings'}[c.kind]))}
function categoryWebMark(c){return c.mark||({salary:'💼',bonus:'✦','other-income':'↗',rent:'⌂',groceries:'▤',transport:'⌁',food:'♨',bills:'▣','other-expense':'✦',emergency:'✓',invest:'↗'}[c.id]||({income:'↗',expense:'✦',saving:'✓'}[c.kind]))}
function exportBook(){return {schemaVersion:1,entries:data.transactions.map(t=>({...t})),accounts:accounts.map(a=>({...a,icon:a.icon||'wallet',color:safeColor(a.color)})),categories:cats.map(c=>({...c,icon:categoryNativeIcon(c),color:safeColor(c.color)})),budgets:{...data.budgets},advanced:data.advanced||AnaAdvanced.fresh()}}
function backupSnapshot(){return {app:'ana-budget',backupVersion:1,exportedAt:new Date().toISOString(),period,book:exportBook()}}
function validBackup(snapshot){
  if(!snapshot||snapshot.app!=='ana-budget'||snapshot.backupVersion!==1||!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(snapshot.period||''))return false;
  let b=snapshot.book;
  if(!b||b.schemaVersion!==1||!Array.isArray(b.entries)||!Array.isArray(b.accounts)||!Array.isArray(b.categories)||!b.budgets||typeof b.budgets!=='object'||Array.isArray(b.budgets)||b.entries.length>50000||b.accounts.length>200||b.categories.length>1000||Object.keys(b.budgets).length>200000)return false;
  let id=v=>typeof v==='string'&&/^[A-Za-z0-9_-]{1,90}$/.test(v),name=v=>typeof v==='string'&&v.trim().length>0&&v.length<=100,kind=v=>['expense','income','saving'].includes(v),money=v=>Number.isSafeInteger(v)&&v>=0&&v<1e15;
  let accountIds=new Set(),categoryKinds=new Map(),entryIds=new Set();
  for(let a of b.accounts){if(!a||!id(a.id)||accountIds.has(a.id)||!name(a.label)||!/^#[0-9a-fA-F]{6}$/.test(a.color||'')||!Number.isSafeInteger(a.openingBalance)||Math.abs(a.openingBalance)>=1e15||typeof a.icon!=='string'||a.icon.length>60)return false;accountIds.add(a.id)}
  for(let c of b.categories){if(!c||!id(c.id)||categoryKinds.has(c.id)||!name(c.label)||!kind(c.kind)||!/^#[0-9a-fA-F]{6}$/.test(c.color||'')||typeof c.icon!=='string'||c.icon.length>60)return false;categoryKinds.set(c.id,c.kind)}
  for(let t of b.entries){if(!t||!id(t.id)||entryIds.has(t.id)||!validDay(t.date)||!kind(t.kind)||!money(t.amount)||t.amount===0||!accountIds.has(t.accountId)||categoryKinds.get(t.categoryId)!==t.kind||typeof t.note!=='string'||t.note.length>160)return false;entryIds.add(t.id)}
  for(let [k,v] of Object.entries(b.budgets)){let match=/^\d{4}-(?:0[1-9]|1[0-2])\|([A-Za-z0-9_-]+)$/.exec(k);if(!match||!categoryKinds.has(match[1])||!money(v))return false}
  return AnaAdvanced.validate(b);
}
function downloadFile(name,text,mime){let blob=new Blob([text],{type:mime}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),1200)}
function downloadBackup(){let snapshot=backupSnapshot();if(loadFault){formError('Backup tidak tersedia selama data lama bermasalah. Unduh data lama mentah dahulu.');return}if(!validBackup(snapshot)){formError('Data aktif tidak valid untuk backup.');return}downloadFile('Moneo-Backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(snapshot,null,2),'application/json;charset=utf-8')}
function exportCsv(){let cells=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'").replace(/"/g,'""')+'"';let rows=[['Tanggal','Jenis','Kategori','Dompet','Nominal (Rp)','Catatan'],...data.transactions.map(t=>[t.date,{expense:'Pengeluaran',income:'Pemasukan',saving:'Tabungan'}[t.kind],cats.find(c=>c.id===t.categoryId)?.label||'',accounts.find(a=>a.id===t.accountId)?.label||'',t.amount,t.note])];downloadFile('Moneo-Transaksi.csv','\ufeff'+rows.map(r=>r.map(cells).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
let pendingRestore=null;
async function restoreFromFile(input){let file=input?.files?.[0];if(!file)return;if(file.size>6000000){formError('File terlalu besar (maksimal 6 MB).');return}let snapshot;try{snapshot=JSON.parse(await file.text())}catch{formError('File bukan JSON yang valid.');return}if(!validBackup(snapshot)){formError('Backup ditolak: format, referensi atau nilai transaksi tidak valid.');return}pendingRestore=snapshot;modal(modHead('Pulihkan seluruh data?','Backup sudah diperiksa; data lokal saat ini akan diganti.')+`<div class="panel" style="background:#f7f6ff;font-size:12px;line-height:1.8">${snapshot.book.entries.length} transaksi · ${snapshot.book.accounts.length} dompet · ${snapshot.book.categories.length} kategori<br>Periode: ${esc(snapshot.period)}</div><p class="backup-note">Pastikan backup data aktif sudah diunduh terlebih dahulu. Pemulihan tidak bisa dibatalkan.</p><button class="save-btn" onclick="applyRestore()">Ya, pulihkan data</button><button class="save-btn secondary" onclick="settings()">Batal</button>`)}
function applyRestore(){if(!pendingRestore||!validBackup(pendingRestore))return;let b=pendingRestore.book;data={categories:b.categories.map(c=>({...c,mark:categoryWebMark(c)})),accounts:b.accounts.map(a=>({...a})),budgets:{...b.budgets},transactions:b.entries.map(e=>({...e})),advanced:b.advanced||AnaAdvanced.fresh()};cats=data.categories;accounts=data.accounts;
  // Legacy PayLater must remain a normal Lainnya wallet without breaking stable transaction references.
  let legacy=accounts.find(a=>a.id==='paylater');if(legacy){let used=new Set(accounts.map(a=>a.id)),replacement='other-account',index=1;while(used.has(replacement))replacement='other-legacy-account-'+index++;legacy.id=replacement;legacy.label='Lainnya'+(index>1?' (lama)':'');data.transactions.forEach(t=>{if(t.accountId==='paylater')t.accountId=replacement})}
  accounts.forEach(a=>{if(typeof a.label==='string'&&a.label.toLowerCase()==='paylater')a.label='Lainnya'});
  data=cleanMoneoSamples(data).data;cats=data.categories;accounts=data.accounts;period=currentPeriod();pendingRestore=null;selectedDate=null;active='home';query='';loadFault=false;rawCache=null;persist();closeModal();render()}
function settings(){modal(modHead('Tentang Moneo','Keuangan pribadi · penyimpanan lokal')+`<p class="hint" style="font-size:12px;line-height:1.7">Moneo v1.1.14 menggunakan data lokal browser, bukan cloud. Pindah perangkat/browser tidak otomatis memindahkan data. Buat backup berkala sebelum mengganti perangkat atau mengganti perangkat.</p>${loadFault?`<p class="backup-note" style="color:#b46350">Data lokal lama tidak bisa dibaca. Unduh salinan mentahnya sebelum reset agar bisa diperiksa dan dipulihkan manual.</p><button class="save-btn" onclick="downloadFile('Moneo-Data-Lama-Rusak.txt',rawCache||'','text/plain')">Unduh data lama mentah</button>`:''}<h3 style="margin:18px 0 7px;font-size:14px;color:#2c2452">Backup & pemulihan</h3>
  <div class="backup-actions"><button class="save-btn secondary" onclick="importCsvStart()">↑ Impor transaksi CSV (pratinjau dahulu)</button><button class="save-btn" onclick="downloadBackup()">↓ Unduh backup JSON</button><button class="save-btn secondary" onclick="document.getElementById('restore-file').click()">↑ Pulihkan backup JSON</button><input hidden type="file" id="restore-file" accept=".json,application/json" onchange="restoreFromFile(this)"><button class="save-btn secondary" onclick="exportCsv()">↓ Ekspor transaksi CSV</button></div><div id="formError" class="error"></div><p class="backup-note">Backup JSON memuat seluruh data keuangan; simpan di tempat pribadi dan jangan unggah ke repository GitHub. CSV hanya untuk laporan, bukan untuk memulihkan aplikasi. Tabungan lama tetap mengurangi saldo sumber; gunakan Transfer dan Target untuk tabungan antar-dompet tanpa mengubah total kekayaan.</p><div class="copyright-about">© 2026 Na. All rights reserved.</div>`)}

function activity(){const selected=selectedDate?.startsWith(period)?selectedDate:null;let transfers=advState().transfers.filter(t=>t.date.startsWith(period)&&(!selected||selected===t.date));
  return activityBase()+`<div class="section-title" style="margin-top:23px">Transfer antar-dompet <button onclick="tab('advanced')">Keuangan ›</button></div><div class="panel adv-panel">${transfers.length?transfers.map(t=>`<div class="adv-row"><div class="adv-row-main"><b>${esc(accounts.find(a=>a.id===t.from)?.label||'?')} → ${esc(accounts.find(a=>a.id===t.to)?.label||'?')}</b><small>${esc(t.date)} · ${show(t.amount)}</small></div><button class="adv-minor" style="width:auto" onclick="openTransfer('${t.id}')">Edit</button></div>`).join(''):'<div class="not-set">Belum ada transfer di periode ini.</div>'}</div>`;
}
// v1.1.8 Offline Advanced. All actions are local and require an explicit tap.
const Adv = globalThis.AnaAdvanced;
function advState(){return Adv.state({advanced:data.advanced});}
function advWrite(book){if(loadFault){alert('Data lokal bermasalah; perbaiki melalui Pengaturan sebelum menyimpan.');return;}data.advanced=book.advanced;persist();closeModal();render();}
function advBook(){return exportBook();}
function advFail(e){formError(e?.message||'Tidak dapat menyimpan perubahan.');}
function advVal(id){return document.getElementById(id)?.value||''}
function advAmount(id){const raw=advVal(id).trim().replace(/[.\s]/g,'');return /^-?\d{1,14}$/.test(raw)?Number(raw):NaN;}
function advOptions(list,selected){return list.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.label||x.name)}</option>`).join('')}
function advField(id,label,placeholder,value='',type='text'){return `<div class="field"><label>${label}</label><input id="${id}" type="${type}" ${type==='text'?'maxlength="160"':''} placeholder="${esc(placeholder)}" value="${esc(value)}"></div>`}
function advSelect(id,label,options){return `<div class="field"><label>${label}</label><select id="${id}">${options}</select></div>`}
function advForm(title,desc,fields,action,button='Simpan'){modal(modHead(title,desc)+fields+`<div class="error" id="formError"></div><button class="save-btn" onclick="${action}">✓ ${button}</button><button class="save-btn secondary" onclick="closeModal();tab('advanced')">Kembali ke Keuangan</button>`)}
function advDate(){const today=Adv.today();return selectedDate?.startsWith(period)?selectedDate:today.startsWith(period)?today:period+'-01'}
function openTransfer(editId=''){const old=advState().transfers.find(t=>t.id===editId);advForm(old?'Edit transfer':'Transfer antar-dompet','Uang berpindah, bukan pemasukan atau pengeluaran.',advSelect('afrom','DOMPET ASAL',advOptions(accounts,old?.from))+advSelect('ato','DOMPET TUJUAN',advOptions(accounts,old?.to||accounts[1]?.id))+advField('aamount','NOMINAL','50000',old?.amount||'')+advField('adate','TANGGAL','',old?.date||advDate(),'date')+advField('anote','CATATAN','Misal: Isi saldo e-wallet',old?.note||''),`saveTransfer('${editId}')`,old?'Simpan transfer':'Transfer uang')}
function saveTransfer(editId=''){try{advWrite(Adv.addTransfer(advBook(),{from:advVal('afrom'),to:advVal('ato'),date:advVal('adate'),amount:advAmount('aamount'),note:advVal('anote')},editId||undefined))}catch(e){advFail(e)}}
function removeTransfer(key){if(!confirm('Hapus transfer ini? Saldo kedua dompet akan dihitung ulang.'))return;try{advWrite(Adv.deleteTransfer(advBook(),key))}catch(e){alert(e.message)}}
function openGoal(editId=''){const old=advState().goals.find(g=>g.id===editId);advForm(old?'Edit tujuan tabungan':'Target tabungan','Alokasi dana tidak mengubah total saldo. Transfer ke rekening khusus dilakukan terpisah.',advField('aname','NAMA TUJUAN','Dana darurat',old?.name||'')+advField('atarget','TARGET (RP)','30000000',old?.target||'')+advField('adue','TENGGAT OPSIONAL','', old?.deadline||'', 'date'),`saveGoal('${editId}')`,old?'Simpan target':'Buat target')}
function saveGoal(editId=''){try{advWrite(Adv.saveGoal(advBook(),{id:editId||undefined,name:advVal('aname'),target:advAmount('atarget'),deadline:advVal('adue')}))}catch(e){advFail(e)}}
function openAllocate(key,release=false){const goal=advState().goals.find(g=>g.id===key);if(!goal)return;advForm(release?'Lepas alokasi':'Alokasikan tabungan',esc(goal.name)+' · Tidak menambah/mengurangi saldo total.',advSelect('awallet','DANA BERADA DI DOMPET',advOptions(accounts))+advField('aamount','NOMINAL (RP)','250000')+advField('adate','TANGGAL','',advDate(),'date'),`saveAllocate('${key}',${release})`,release?'Lepas alokasi':'Alokasikan')}
function saveAllocate(key,release){try{const a=advAmount('aamount');advWrite(Adv.allocate(advBook(),{goalId:key,accountId:advVal('awallet'),amount:release?-a:a,date:advVal('adate')}))}catch(e){advFail(e)}}
function removeGoal(key){if(!confirm('Hapus tujuan tabungan? Alokasi harus nol.'))return;try{advWrite(Adv.deleteGoal(advBook(),key))}catch(e){alert(e.message)}}
function openRecurring(editId=''){const old=advState().recurring.find(r=>r.id===editId);advForm(old?'Edit jadwal bulanan':'Transaksi berulang','Jadwal bulanan tidak langsung mengubah saldo. Tekan Catat jadwal ketika jatuh tempo.',advField('aname','NAMA JADWAL','Gaji setiap bulan',old?.name||'')+advSelect('akind','JENIS',`<option value="expense">Pengeluaran</option><option value="income">Pemasukan</option><option value="saving">Tabungan lama</option>`)+`<div class="field"><label>KATEGORI</label><select id="acategory"></select></div>`+advSelect('awallet','DOMPET',advOptions(accounts,old?.accountId))+advField('aamount','NOMINAL','500000',old?.amount||'')+advField('adate','TANGGAL PERTAMA','',old?.startDate||advDate(),'date'),`saveRecurring('${editId}')`,old?'Simpan jadwal':'Tambah jadwal');document.getElementById('akind').addEventListener('change',advRecurringCategories);document.getElementById('akind').value=old?.kind||'expense';advRecurringCategories();document.getElementById('acategory').value=old?.categoryId||cats.find(c=>c.kind==='expense')?.id||'';}
function advRecurringCategories(){let k=advVal('akind'),el=document.getElementById('acategory');if(el)el.innerHTML=advOptions(cats.filter(c=>c.kind===k));}
function saveRecurring(editId=''){try{advWrite(Adv.addRecurring(advBook(),{name:advVal('aname'),kind:advVal('akind'),categoryId:advVal('acategory'),accountId:advVal('awallet'),amount:advAmount('aamount'),startDate:advVal('adate')},editId||undefined))}catch(e){advFail(e)}}
function postRecurring(){const today=Adv.today(),due=Adv.scheduled(advBook(),today);if(!due.length){alert('Belum ada jadwal yang jatuh tempo bulan ini.');return;}if(!confirm(`Catat ${due.length} transaksi yang jatuh tempo hingga ${today}?`))return;try{const next=Adv.postDue(advBook(),today);data.transactions=next.entries;persist();render();alert(`${due.length} transaksi dicatat. Jadwal yang sama tidak akan digandakan.`)}catch(e){alert(e.message)}}
function toggleRecurring(key){advWrite(Adv.toggleRecurring(advBook(),key))}
function removeRecurring(key){if(!confirm('Hapus jadwal? Transaksi yang sudah dicatat tidak akan dihapus.'))return;advWrite(Adv.deleteRecurring(advBook(),key))}
function openDebt(){advForm('Catat utang atau piutang','Hanya pokok pinjaman. Pencairan dicatat pada saldo rekening dan diimbangi sebagai utang/piutang.',advField('aname','NAMA PIHAK','Misal: Pinjaman koperasi')+advSelect('atype','JENIS','<option value="payable">Saya berutang (uang masuk)</option><option value="receivable">Saya memberi pinjaman (uang keluar)</option>')+advSelect('awallet','DOMPET PENCAIRAN',advOptions(accounts))+advField('aamount','POKOK PINJAMAN','1000000')+advField('adate','TANGGAL','',advDate(),'date'),'saveDebt()','Simpan pinjaman')}
function saveDebt(){try{advWrite(Adv.addDebt(advBook(),{name:advVal('aname'),type:advVal('atype'),accountId:advVal('awallet'),principal:advAmount('aamount'),date:advVal('adate')}))}catch(e){advFail(e)}}
function openPayDebt(key){const d=advState().debts.find(x=>x.id===key);if(!d)return;advForm('Catat pelunasan',esc(d.name)+' · Sisa '+money(Adv.debtRemaining(advBook(),key)),advSelect('awallet','DOMPET',advOptions(accounts))+advField('aamount','NOMINAL','250000')+advField('adate','TANGGAL','',advDate(),'date'),`saveDebtPayment('${key}')`,'Catat pelunasan')}
function saveDebtPayment(key){try{advWrite(Adv.payDebt(advBook(),{debtId:key,accountId:advVal('awallet'),amount:advAmount('aamount'),date:advVal('adate')}))}catch(e){advFail(e)}}
function removePayment(key){if(!confirm('Urungkan pelunasan ini? Saldo dan sisa utang akan dihitung ulang.'))return;try{advWrite(Adv.deletePayment(advBook(),key))}catch(e){alert(e.message)}}
function removeDebt(key){if(!confirm('Hapus pinjaman? Pelunasan harus kosong.'))return;try{advWrite(Adv.deleteDebt(advBook(),key))}catch(e){alert(e.message)}}
function openReconcile(){advForm('Rekonsiliasi saldo','Cocokkan saldo aplikasi dengan dompet asli. Selisih dicatat sebagai penyesuaian, bukan pengeluaran/pemasukan.',advSelect('awallet','DOMPET',advOptions(accounts))+advField('aactual','SALDO ASLI (RP)','1000000')+advField('adate','TANGGAL','',advDate(),'date'),'saveReconcile()','Cocokkan saldo')}
function saveReconcile(){try{const n=advVal('aactual').trim().replace(/[.\s]/g,'');if(!/^-?\d{1,14}$/.test(n))throw Error('Saldo asli harus angka Rupiah.');advWrite(Adv.reconcile(advBook(),{accountId:advVal('awallet'),actual:Number(n),date:advVal('adate')}))}catch(e){advFail(e)}}
function removeAdjustment(key){if(!confirm('Batalkan penyesuaian saldo ini?'))return;advWrite(Adv.deleteAdjustment(advBook(),key))}
function saveAdvSettings(){try{advWrite(Adv.setOptions(advBook(),{rollover:document.getElementById('rollover').checked,alertPercent:Number(advVal('warning'))}))}catch(e){advFail(e)}}
function advBadge(t){return `<span class="adv-badge">${t}</span>`}
function advancedPage(){let s=advState(),b=advBook(),forecast=Adv.forecast(b,period),warnings=cats.filter(c=>c.kind==='expense').map(c=>({c,limit:Adv.plannedBudget(b,period,c.id),spent:catSum(period,c.id)})).filter(x=>x.limit>0&&x.spent/x.limit*100>=s.settings.alertPercent);
 const goals=s.goals.map(g=>{let saved=Adv.goalBalance(b,g.id),pct=Math.min(100,saved/g.target*100);return `<div class="adv-row"><div class="adv-row-main"><b>${esc(g.name)}</b><small>${show(saved)} / ${show(g.target)} · ${Math.floor(pct)}%${g.deadline?' · '+esc(g.deadline):''}</small>${progress(pct/100,'#7063e8')}</div><div class="adv-actions"><button onclick="openGoal('${g.id}')">Edit</button><button onclick="openAllocate('${g.id}')">+ Alokasi</button><button onclick="openAllocate('${g.id}',true)">− Lepas</button><button class="adv-danger" onclick="removeGoal('${g.id}')">×</button></div></div>`}).join('')||'<div class="not-set">Belum ada target tabungan.</div>';
 const transfers=s.transfers.filter(t=>t.date.slice(0,7)===period).slice(0,10).map(t=>`<div class="adv-row"><div class="adv-row-main"><b>${esc(accounts.find(a=>a.id===t.from)?.label||'')} → ${esc(accounts.find(a=>a.id===t.to)?.label||'')}</b><small>${t.date} · ${show(t.amount)}${t.note?' · '+esc(t.note):''}</small></div><div class="adv-actions"><button onclick="openTransfer('${t.id}')">Edit</button><button class="adv-danger" onclick="removeTransfer('${t.id}')">Hapus</button></div></div>`).join('')||'<div class="not-set">Belum ada transfer bulan ini.</div>';
 const schedules=s.recurring.map(r=>`<div class="adv-row"><div class="adv-row-main"><b>${esc(r.name)} ${r.active?advBadge('Aktif'):advBadge('Jeda')}</b><small>${show(r.amount)} · Tanggal ${Number(r.startDate.slice(8))} tiap bulan</small></div><div class="adv-actions"><button onclick="openRecurring('${r.id}')">Edit</button><button onclick="toggleRecurring('${r.id}')">${r.active?'Jeda':'Aktifkan'}</button><button class="adv-danger" onclick="removeRecurring('${r.id}')">×</button></div></div>`).join('')||'<div class="not-set">Belum ada jadwal bulanan.</div>';
 const debts=s.debts.map(d=>`<div class="adv-row"><div class="adv-row-main"><b>${esc(d.name)} ${advBadge(d.type==='payable'?'Utang':'Piutang')}</b><small>Sisa ${show(Adv.debtRemaining(b,d.id))} / ${show(d.principal)}</small>${s.payments.filter(p=>p.debtId===d.id).map(p=>`<small>↳ ${p.date} · ${show(p.amount)} <button class="adv-danger" onclick="removePayment('${p.id}')">Urungkan</button></small>`).join('')}</div><div class="adv-actions"><button onclick="openPayDebt('${d.id}')">Bayar</button><button class="adv-danger" onclick="removeDebt('${d.id}')">×</button></div></div>`).join('')||'<div class="not-set">Belum ada utang/piutang.</div>';
 const adjustments=s.adjustments.slice(0,5).map(a=>`<div class="adv-row"><div class="adv-row-main"><b>${esc(accounts.find(x=>x.id===a.accountId)?.label||'')} · ${show(a.delta)}</b><small>${a.date} · Penyesuaian</small></div><button class="adv-danger" onclick="removeAdjustment('${a.id}')">Urungkan</button></div>`).join('');
 const due=Adv.scheduled(b,Adv.today());
 return `<div class="headline">Keuangan</div><div class="subhead">Fitur lanjutan 100% lokal · tanpa akun, AI berbayar, WhatsApp, atau sinkronisasi.</div>
  <div class="adv-hero"><small>TOTAL KEKAYAAN BERSIH</small><strong>${show(Adv.netWorth(b))}</strong><span>Saldo dompet ${show(Adv.totalBalance(b))} · termasuk utang/piutang</span></div>
  ${warnings.length?`<div class="adv-alert">⚠ ${warnings.length} kategori melewati ${s.settings.alertPercent}% target: ${warnings.slice(0,3).map(x=>esc(x.c.label)).join(', ')}</div>`:''}
  ${due.length?`<div class="adv-alert">▦ Ada ${due.length} transaksi berulang jatuh tempo. <button onclick="postRecurring()">Catat sekarang</button></div>`:''}
  <div class="adv-grid"><button onclick="openTransfer()">⇄<b>Transfer</b><small>Antar-dompet</small></button><button onclick="openGoal()">◎<b>Target</b><small>Tabungan</small></button><button onclick="openRecurring()">▦<b>Berulang</b><small>Bulanan</small></button><button onclick="openDebt()">↗<b>Utang</b><small>& piutang</small></button><button onclick="openReconcile()">≋<b>Cek saldo</b><small>Rekonsiliasi</small></button></div>
  ${head('Transfer · '+monthlabel(period))}<div class="panel adv-panel">${transfers}</div>
  ${head('Target tabungan')}<div class="panel adv-panel">${goals}<p class="adv-hint">Alokasi adalah pemisahan saldo secara virtual, bukan transfer atau pengeluaran. Dompet sumber tetap memiliki uang tersebut.</p></div>
  ${head('Transaksi rutin')}<div class="panel adv-panel">${schedules}<button class="adv-minor" onclick="postRecurring()">✓ Catat jadwal jatuh tempo bulan ini</button><p class="adv-hint">Jadwal hanya dicatat setelah tombol ditekan. Tidak ada sistem otomatis di latar belakang.</p></div>
  ${head('Utang & piutang')}<div class="panel adv-panel">${debts}<p class="adv-hint">Hanya pokok pinjaman. Bunga/biaya tambahan dicatat terpisah sebagai pengeluaran.</p></div>
  ${head('Rekonsiliasi terbaru')}<div class="panel adv-panel">${adjustments||'<div class="not-set">Belum ada penyesuaian saldo.</div>'}</div>
  ${head('Prediksi saldo dari jadwal')}<div class="panel"><div class="flex"><span>Belum dicatat (${monthlabel(period)})</span><b>${forecast.pending.length} jadwal</b></div><div class="flex" style="margin-top:10px"><span class="hint">Estimasi setelah jadwal</span><b>${show(forecast.projected)}</b></div><p class="adv-hint">Hanya menghitung transaksi berulang yang belum dicatat, bukan prediksi AI.</p></div>
  ${head('Aturan anggaran')}<div class="panel adv-settings"><label><input id="rollover" type="checkbox" ${s.settings.rollover?'checked':''}> Sisa anggaran pengeluaran dibawa ke bulan berikutnya (maksimal histori 12 bulan)</label><div class="field"><label>PERINGATAN PEMAKAIAN ANGGARAN</label><select id="warning"><option value="70" ${s.settings.alertPercent===70?'selected':''}>70%</option><option value="80" ${s.settings.alertPercent===80?'selected':''}>80%</option><option value="90" ${s.settings.alertPercent===90?'selected':''}>90%</option><option value="100" ${s.settings.alertPercent===100?'selected':''}>100%</option></select></div><button class="save-btn" onclick="saveAdvSettings()">Simpan pengaturan</button></div>
  `;
}
// Simple RFC4180-style parser for the CSV exported by Moneo, with quoting, BOM and CRLF.
function parseCsv(s){const rows=[];let row=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(q){if(c==='"'&&s[i+1]==='"'){v+='"';i++}else if(c==='"')q=false;else v+=c;}else if(c==='"')q=true;else if(c===','){row.push(v);v=''}else if(c==='\n'){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v=''}else v+=c;}if(q)throw Error('Kutip CSV tidak tertutup.');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
let pendingCsv=[];
function importCsvStart(){modal(modHead('Impor CSV offline','Gunakan format hasil Ekspor CSV Moneo. Pratinjau dan validasi sebelum menyimpan.')+`<div class="field"><label>PILIH BERKAS CSV</label><input id="csv-file" type="file" accept=".csv,text/csv" onchange="previewImportCsv(this)"></div><div class="error" id="formError"></div><button class="save-btn secondary" onclick="settings()">Batal</button>`)}
async function previewImportCsv(input){let f=input?.files?.[0];if(!f)return;try{if(f.size>4e6)throw Error('CSV maksimal 4 MB.');const rows=parseCsv((await f.text()).replace(/^\uFEFF/,''));const required=['Tanggal','Jenis','Kategori','Dompet','Nominal (Rp)','Catatan'];if(!rows.length||rows[0].length!==6||rows[0].some((x,i)=>x!==required[i]))throw Error('Header CSV tidak sesuai format ekspor Moneo.');const seen=new Set(data.transactions.map(t=>[t.date,t.kind,t.categoryId,t.accountId,t.amount,t.note].join('|')));let fresh=[],duplicates=0;for(const row of rows.slice(1)){if(!row.some(x=>x.trim()))continue;if(row.length!==6)throw Error('CSV memiliki kolom yang tidak lengkap.');const kind={Pemasukan:'income',Pengeluaran:'expense',Tabungan:'saving'}[row[1]],cat=cats.find(c=>c.label===row[2]&&c.kind===kind),acct=accounts.find(a=>a.label===row[3]),amt=Number(row[4].replace(/\./g,''));if(!validDay(row[0])||!cat||!acct||!Number.isSafeInteger(amt)||amt<=0||amt>=1e15||row[5].length>160)throw Error('Ada transaksi dengan tanggal, kategori, dompet, atau nominal tidak valid.');const key=[row[0],kind,cat.id,acct.id,amt,row[5]].join('|');if(seen.has(key)){duplicates++;continue;}seen.add(key);fresh.push({id:makeId('import'),date:row[0],kind,categoryId:cat.id,accountId:acct.id,amount:amt,note:row[5]});if(fresh.length>10000)throw Error('Impor maksimal 10.000 transaksi sekaligus.');}pendingCsv=fresh;modal(modHead('Pratinjau impor CSV','Berkas belum mengubah data lokal.')+`<div class="panel"><b>${fresh.length} transaksi baru</b><p class="hint">${duplicates} baris duplikat dilewati.</p>${fresh.slice(0,4).map(t=>`<p class="hint">${t.date} · ${esc(cats.find(c=>c.id===t.categoryId)?.label||'')} · ${money(t.amount)}</p>`).join('')}</div><button class="save-btn" onclick="commitCsv()" ${fresh.length?'':'disabled'}>Impor ${fresh.length} transaksi</button><button class="save-btn secondary" onclick="importCsvStart()">Kembali</button>`);}catch(e){pendingCsv=[];formError(e.message);}}
function commitCsv(){if(loadFault||!pendingCsv.length)return;data.transactions.unshift(...pendingCsv);const n=pendingCsv.length;pendingCsv=[];persist();closeModal();render();alert(`${n} transaksi diimpor. Backup JSON disarankan.`);}

render();
